sys_script_include.script:
var IncidentsForUser = Class.create();
IncidentsForUser.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
  getRecentIncidents: function () {
    var userId = gs.getUserID();

    var stateGroup = (this.getParameter("sysparm_state_group") || "open").toLowerCase(); // open|closed|all
    var sortBy = this.getParameter("sysparm_sort_by") || "sys_updated_on"; // whitelist below
    var sortDir = (this.getParameter("sysparm_sort_dir") || "desc").toLowerCase(); // asc|desc
    var page = parseInt(this.getParameter("sysparm_page"), 10);
    var pageSize = parseInt(this.getParameter("sysparm_page_size"), 10);

    if (isNaN(page) || page < 0) page = 0;
    if (isNaN(pageSize) || pageSize < 5 || pageSize > 100) pageSize = 10;

    var allowedSort = { number: true, short_description: true, state: true, sys_updated_on: true };
    if (!allowedSort[sortBy]) sortBy = "sys_updated_on";
    if (sortDir !== "asc" && sortDir !== "desc") sortDir = "desc";

    // Build common query
    var base = "caller_id=" + userId;

    // Typical Incident states: 6=Resolved, 7=Closed, 8=Canceled (may vary by instance)
    if (stateGroup === "open") base += "^stateNOT IN6,7,8";
    else if (stateGroup === "closed") base += "^stateIN6,7,8";
    // else "all" => no extra filter

    // Total count
    var ga = new GlideAggregate("incident");
    ga.addEncodedQuery(base);
    ga.addAggregate("COUNT");
    ga.query();
    var total = 0;
    if (ga.next()) total = parseInt(ga.getAggregate("COUNT"), 10) || 0;

    // Page query
    var start = page * pageSize;
    var end = start + pageSize;

    var gr = new GlideRecord("incident");
    gr.addEncodedQuery(base);

    if (sortDir === "asc") gr.orderBy(sortBy);
    else gr.orderByDesc(sortBy);

    gr.chooseWindow(start, end);
    gr.query();

    var rows = [];
    while (gr.next()) {
      rows.push({
        sys_id: gr.getUniqueValue(),
        number: gr.getValue("number"),
        short_description: gr.getValue("short_description"),
        state: gr.getDisplayValue("state"),
        sys_updated_on: gr.getDisplayValue("sys_updated_on")
      });
    }

    return new global.JSON().encode({
      page: page,
      pageSize: pageSize,
      total: total,
      rows: rows
    });
  },

  type: "IncidentsForUser"
});
